  "Template not found.": "\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0642\u0627\u0644\u0628",
  "Template unavailable": "\u0627\u0644\u0642\u0627\u0644\u0628 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d",
  "Templates overview": "\u0646\u0638\u0631\u0629 \u0639\u0627\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0642\u0648\u0627\u0644\u0628",
  "Temporary SurveyJS Preview": "\u0645\u0639\u0627\u064a\u0646\u0629 SurveyJS \u0627\u0644\u0645\u0624\u0642\u062a\u0629",
  "Temporary form is available and can be previewed, refined, or stored as new version.": "\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u0624\u0642\u062a \u0645\u062a\u0648\u0641\u0631 \u0648\u064a\u0645\u0643\u0646 \u0645\u0639\u0627\u064a\u0646\u062a\u0647 \u0648\u062a\u062d\u0633\u064a\u0646\u0647 \u0623\u0648 \u062d\u0641\u0638\u0647 \u0643\u0646\u0633\u062e\u0629 \u062c\u062f\u064a\u062f\u0629.",
  "Text (.txt)": "\u0646\u0635 (.txt)",
  "The Creator and Dashboard components require a SurveyJS license for production use.": "\u062a\u062a\u0637\u0644\u0628 \u0645\u0643\u0648\u0646\u0627\u062a Creator \u0648Dashboard \u062a\u0631\u062e\u064a\u0635 SurveyJS \u0644\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0641\u064a \u0627\u0644\u0625\u0646\u062a\u0627\u062c.",
  "The following fields were extracted from the uploaded PDF template.": "The following fields were extracted from the uploaded PDF template.",
  "The maintainer of this add-on is happy to help \u2014 reach out at": "\u064a\u0633\u0631 \u0645\u0634\u0631\u0641 \u0647\u0630\u0647 \u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0645\u0633\u0627\u0639\u062f\u062a\u0643 \u2014 \u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0639\u0644\u0649",
  "The template JSON could not be loaded.": "\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0642\u0627\u0644\u0628 JSON",
