  "There are no survey responses yet. Once users submit the survey, their responses will appear here.": "\u0644\u0627 \u062a\u0648\u062c\u062f \u0627\u0633\u062a\u062c\u0627\u0628\u0627\u062a \u0627\u0633\u062a\u0637\u0644\u0627\u0639 \u062d\u062a\u0649 \u0627\u0644\u0622\u0646. \u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u064a\u0642\u062f\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0648\u0646 \u0627\u0644\u0627\u0633\u062a\u0637\u0644\u0627\u0639 \u060c \u0633\u062a\u0638\u0647\u0631 \u0631\u062f\u0648\u062f\u0647\u0645 \u0647\u0646\u0627.",
  "This action permanently removes the selected version. This cannot be undone.": "\u064a\u0632\u064a\u0644 \u0647\u0630\u0627 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0625\u0635\u062f\u0627\u0631 \u0627\u0644\u0645\u062d\u062f\u062f \u0646\u0647\u0627\u0626\u064a\u064b\u0627. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0647\u0630\u0627.",
  "This action will permanently delete all survey results. This cannot be undone.": "\u0633\u064a\u0624\u062f\u064a \u0647\u0630\u0627 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0625\u0644\u0649 \u062d\u0630\u0641 \u062c\u0645\u064a\u0639 \u0646\u062a\u0627\u0626\u062c \u0627\u0644\u0627\u0633\u062a\u0637\u0644\u0627\u0639 \u0646\u0647\u0627\u0626\u064a\u064b\u0627. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0647\u0630\u0627.",
  "This feature is experimental. Please review the generated form carefully.": "\u0647\u0630\u0647 \u0627\u0644\u0645\u064a\u0632\u0629 \u062a\u062c\u0631\u064a\u0628\u064a\u0629. \u064a\u0631\u062c\u0649 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0630\u064a \u062a\u0645 \u0625\u0646\u0634\u0627\u0624\u0647 \u0628\u0639\u0646\u0627\u064a\u0629.",
  "This form requires a trusted access link. Please use the link provided by the form owner.": "\u064a\u062a\u0637\u0644\u0628 \u0647\u0630\u0627 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0631\u0627\u0628\u0637 \u0648\u0635\u0648\u0644 \u0645\u0648\u062b\u0648\u0642\u0627 \u0627\u0644\u0631\u062c\u0627\u0621 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0631\u0627\u0628\u0637 \u0627\u0644\u0630\u064a \u0648\u0641\u0631\u0647 \u0645\u0627\u0644\u0643 \u0627\u0644\u0646\u0645\u0648\u0630\u062c",
  "This is a demo page for demonstrating the embedded mode using the survey's iframe viewer.": "This is a demo page for demonstrating the embedded mode using the survey's iframe viewer.",
  "This is a helper to get started, not a finished form.": "\u0647\u0630\u0627 \u0645\u0633\u0627\u0639\u062f \u0644\u0644\u0628\u062f\u0621 \u060c \u0648\u0644\u064a\u0633 \u0646\u0645\u0648\u0630\u062c\u064b\u0627 \u0646\u0647\u0627\u0626\u064a\u064b\u0627.",
  "This survey hasn't received any submissions. Once respondents complete the form, their results will appear here.": "\u0644\u0645 \u064a\u0633\u062a\u0644\u0645 \u0647\u0630\u0627 \u0627\u0644\u0627\u0633\u062a\u0628\u064a\u0627\u0646 \u0623\u064a \u0631\u062f\u0648\u062f \u0628\u0639\u062f. \u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u064a\u0643\u0645\u0644 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646 \u0627\u0644\u0646\u0645\u0648\u0630\u062c\u060c \u0633\u062a\u0638\u0647\u0631 \u0646\u062a\u0627\u0626\u062c\u0647\u0645 \u0647\u0646\u0627.",
  "This survey is not configured to be embedded. Please contact the survey administrator.": "\u0647\u0630\u0627 \u0627\u0644\u0627\u0633\u062a\u0637\u0644\u0627\u0639 \u063a\u064a\u0631 \u0645\u0647\u064a\u0623 \u0644\u064a\u062a\u0645 \u062a\u0636\u0645\u064a\u0646\u0647. \u064a\u0631\u062c\u0649 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0627\u0633\u062a\u0637\u0644\u0627\u0639.",
  "This template will be created next to the current survey.": "\u0633\u064a\u062a\u0645 \u0625\u0646\u0634\u0627\u0621 \u0647\u0630\u0627 \u0627\u0644\u0642\u0627\u0644\u0628 \u0628\u062c\u0627\u0646\u0628 \u0627\u0644\u0627\u0633\u062a\u0628\u064a\u0627\u0646 \u0627\u0644\u062d\u0627\u0644\u064a",
  "This will permanently delete the selected result. This cannot be undone.": "\u0633\u064a\u0624\u062f\u064a \u0647\u0630\u0627 \u0625\u0644\u0649 \u062d\u0630\u0641 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0646\u0647\u0627\u0626\u064a\u064b\u0627. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0647\u0630\u0627.",
