  "Upload a PDF form and generate SurveyJS JSON from it": "\u0642\u0645 \u0628\u062a\u062d\u0645\u064a\u0644 \u0646\u0645\u0648\u0630\u062c PDF \u0648\u0625\u0646\u0634\u0627\u0621 SurveyJS JSON \u0645\u0646\u0647",
  "Upload a fillable PDF form (.pdf file only)": "Upload a fillable PDF form (.pdf file only)",
  "Upload a fillable PDF to generate a SurveyJS form and enable PDF-based submissions.": "\u0642\u0645 \u0628\u062a\u062d\u0645\u064a\u0644 \u0645\u0644\u0641 PDF \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0639\u0628\u0626\u0629 \u0644\u0625\u0646\u0634\u0627\u0621 \u0646\u0645\u0648\u0630\u062c SurveyJS \u0648\u062a\u0645\u0643\u064a\u0646 \u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629 \u0639\u0644\u0649 PDF",
  "Upload a source document and generate a temporary SurveyJS form draft with AI.": "\u062d\u0645\u0651\u0644 \u0645\u0633\u062a\u0646\u062f \u0645\u0635\u062f\u0631 \u0648\u0623\u0646\u0634\u0626 \u0645\u0633\u0648\u062f\u0629 \u0646\u0645\u0648\u0630\u062c SurveyJS \u0645\u0624\u0642\u062a\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a.",
  "Upload a valid SurveyJS JSON file to create a new version. The file will be validated before saving.": "\u0642\u0645 \u0628\u062a\u062d\u0645\u064a\u0644 \u0645\u0644\u0641 SurveyJS JSON \u0635\u0627\u0644\u062d \u0644\u0625\u0646\u0634\u0627\u0621 \u0625\u0635\u062f\u0627\u0631 \u062c\u062f\u064a\u062f. \u0633\u064a\u062a\u0645 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0645\u0644\u0641 \u0642\u0628\u0644 \u0627\u0644\u062d\u0641\u0638.",
  "Upload and Convert": "\u062a\u062d\u0645\u064a\u0644 \u0648\u062a\u062d\u0648\u064a\u0644",
  "Upload and Create Version": "\u062a\u062d\u0645\u064a\u0644 \u0648\u0625\u0646\u0634\u0627\u0621 \u0625\u0635\u062f\u0627\u0631",
  "Upload documents and convert them to SurveyJS forms using AI": "\u062d\u0645\u0651\u0644 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0648\u062d\u0648\u0651\u0644\u0647\u0627 \u0625\u0644\u0649 \u0646\u0645\u0627\u0630\u062c SurveyJS \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a",
